50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	};
60	
61	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
62	
63	const quote = ({ items }: QuoteStep): QuoteResult => {
64	  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
65	
66	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
67	
68	  const premiumBeforeRounding =
69	    policyBase + firstInsuranceSurcharge + PROCESSING_FEE;
70	
71	  return { premium: Math.ceil(premiumBeforeRounding) };
72	};
73	
74	const runStep = (step: Step): StepResult => {
75	  if (step.op === "quote") return quote(step);
76	
77	  throw new Error(`unsupported step: ${step.op}`);
78	};
79	
80	export const runScenario = (scenario: Scenario): ScenarioResult => ({
81	  results: scenario.steps.map(runStep),
82	});
